<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acesso privado de RH</title><style>body{font:16px/1.5 system-ui,sans-serif;background:#f3f4f6;color:#334155;margin:0;padding:24px}main{max-width:850px;margin:auto;background:#fff;padding:32px;border-radius:8px}fieldset{border:1px solid #cbd5e1;margin:20px 0;padding:16px}label{display:block;margin:10px 0}button{padding:10px 16px;font:inherit;background:#166534;color:white;border:0;border-radius:4px}a{color:#166534}.alert{padding:16px;background:#fef3c7}pre{white-space:pre-wrap;font:inherit}</style></head><body><main>
<h1>Acesso privado de RH</h1><?php if($error!==null){?><p role="alert" class="alert"><?= $esc($error); ?></p><?php } ?>
<?php if($result!==null){?><p role="status"><?php if(isset($result['score'])){?>Tentativa confirmada: <?= (int)$result['score']; ?>%. <?= $result['passed']?'Aprovado.':'Confira o limite de tentativas.'; ?><?php }else{?>Ciência registrada. Este registro não constitui assinatura digital ou certificação jurídica.<?php } ?></p><?php } ?>
<?php if($view!==null){?><p>Validade deste acesso: <?= $esc($view['expires_at']); ?> UTC.</p>
<?php if($view['purpose']==='training'){$r=$view['object'];?><h2><?= $esc($r['course']['title']); ?></h2><p><?= nl2br($esc($r['course']['description'])); ?></p><p>Prazo: <?= $esc($r['due_at']); ?> UTC · <?= $esc($r['timezone']); ?>. Mínimo para aprovação: <?= (int)$r['course']['pass_percent']; ?>%. Tentativas: <?= (int)$r['attempt_count']; ?>/<?= (int)$r['course']['max_attempts']; ?>.</p><ul><?php foreach($r['materials'] as $f){?><li><a href="<?= $esc($action_url.'?file='.$f['id']); ?>" rel="noreferrer">Baixar material #<?= (int)$f['id']; ?></a></li><?php } ?></ul>
<?php if($r['state']==='assigned'){echo form_open($action_url,['id'=>'hr-participant-training']);?><input type="hidden" name="participant_csrf" value="<?= $esc($participant_csrf); ?>"><input type="hidden" name="request_key" value="<?= $esc($request_key); ?>"><input type="hidden" name="revision" value="<?= (int)$view['revision']; ?>"><?php foreach($r['course']['questions'] as $n=>$q){?><fieldset><legend><?= ($n+1).'. '.$esc($q['question']); ?></legend><?php foreach($q['choices'] as $answer=>$label){?><label><input type="radio" name="answers[<?= (int)$n; ?>]" value="<?= (int)$answer; ?>" required> <?= $esc($label); ?></label><?php } ?></fieldset><?php } ?><button type="submit">Confirmar respostas</button><?= form_close(); ?><?php }else{?><p>Estado da atribuição: <?= $esc(['passed'=>'Aprovado','failed'=>'Tentativas encerradas','cancelled'=>'Cancelado'][$r['state']]??$r['state']); ?>.</p><?php } ?>
<?php }else{$c=$view['object']['snapshot'];?><h2>Contrato de vínculo <?= (int)$c['number']; ?></h2><p><?= $esc($c['company']['legal_name']); ?> · <?= $esc($c['company']['tax_id']??''); ?></p><p>Pessoa: <?= $esc($c['employee']['name']); ?> · <?= $esc($c['employee']['employee_code']); ?></p><p>Tipo: <?= $esc($c['type']); ?>. Vigência: <?= $esc($c['starts_on']); ?> até <?= $esc($c['ends_on']??'prazo aberto'); ?>.</p><p>Valor informado: <?= $esc($c['terms']['currency']); ?> <?= $esc(number_format($c['terms']['salary_minor']/100,2,',','.')); ?>. Horas semanais informadas: <?= (int)$c['terms']['hours_per_week']; ?>.</p><h3>Atividades</h3><pre><?= $esc($c['terms']['job_description']); ?></pre><h3>Condições confirmadas</h3><pre><?= $esc($c['terms']['text']); ?></pre>
<?php if($view['object']['acknowledged_at']===null){echo form_open($action_url,['id'=>'hr-participant-contract']);?><input type="hidden" name="participant_csrf" value="<?= $esc($participant_csrf); ?>"><input type="hidden" name="request_key" value="<?= $esc($request_key); ?>"><input type="hidden" name="revision" value="<?= (int)$view['revision']; ?>"><label><input type="checkbox" name="answers[acknowledge]" value="1" required> Li o documento e registro minha ciência. Este registro não constitui assinatura digital ou certificação jurídica.</label><button type="submit">Registrar ciência</button><?= form_close(); ?><?php }else{?><p>Ciência registrada em <?= $esc($view['object']['acknowledged_at']); ?> UTC.</p><?php } } } ?>
